#!/usr/bin/env bash
# shellcheck disable=SC2031  # $T is set per test by run_test (tests/lib/assert.sh)
# Tests for .claude/scripts/guard-generated.sh, the Claude Code PreToolUse hook
# that blocks Edit/Write on generated files (a `Code generated … DO NOT EDIT`
# line in the first five lines).
set -uo pipefail
# shellcheck source=../lib/assert.sh
source "$(dirname "${BASH_SOURCE[0]}")/../lib/assert.sh"

GUARD="$REPO_ROOT/.claude/scripts/guard-generated.sh"

# Exit status of the guard for an Edit payload on path $1.
guard_status() {
  jq -cn --arg p "$1" '{tool_name: "Edit", tool_input: {file_path: $p}}' | bash "$GUARD" >/dev/null 2>&1
  echo $?
}

# Why this test is important:
#   - Go generators (mockgen, wire, protoc) all use this header; an edit to
#     their output is lost on the next regenerate.
# What it tests:
#   - A file headed `// Code generated by mockgen. DO NOT EDIT.` is blocked,
#     and the reason names the file.
test_blocks_go_generated() {
  printf '// Code generated by mockgen. DO NOT EDIT.\npackage mocks\n' > "$T/mock.go"
  assert_eq 2 "$(guard_status "$T/mock.go")" "exit for a mockgen file"
  local err
  err=$(jq -cn --arg p "$T/mock.go" '{tool_input: {file_path: $p}}' | bash "$GUARD" 2>&1 >/dev/null)
  assert_contains "$err" "generated file" "reason"
  assert_contains "$err" "$T/mock.go" "reason names the file"
}

# Why this test is important:
#   - A one-line generated file often has no trailing newline; `read` returns
#     non-zero on that partial line, so a naive loop never tests it.
# What it tests:
#   - A file whose only line is the marker, without a newline, is blocked.
test_blocks_marker_without_trailing_newline() {
  printf '// Code generated by mockgen. DO NOT EDIT.' > "$T/one.go"
  assert_eq 2 "$(guard_status "$T/one.go")" "exit for an unterminated marker line"
}

# Why this test is important:
#   - claude-gen puts its marker inside frontmatter (line 2), not on line 1.
# What it tests:
#   - A rule file with the marker as a YAML comment on line 2 is blocked.
test_blocks_marker_in_frontmatter() {
  printf -- '---\n# Code generated by claude-gen; DO NOT EDIT.\npaths: ["*.go"]\n---\nbody\n' > "$T/rule.md"
  assert_eq 2 "$(guard_status "$T/rule.md")" "exit for a generated rule"
}

# Why this test is important:
#   - The hook runs on every edit in every project; it must not block normal work.
# What it tests:
#   - A plain source file is allowed.
test_allows_plain_file() {
  printf 'package main\n' > "$T/main.go"
  assert_eq 0 "$(guard_status "$T/main.go")" "exit for a plain file"
}

# Why this test is important:
#   - Docs and tests mention the phrase; only a header marks a file generated.
# What it tests:
#   - The phrase on line 9 does not block.
test_allows_late_mention() {
  printf '1\n2\n3\n4\n5\n6\n7\n8\nCode generated by x; DO NOT EDIT.\n' > "$T/notes.md"
  assert_eq 0 "$(guard_status "$T/notes.md")" "exit for a late mention"
}

# Why this test is important:
#   - Write creates new files; a missing path is not generated output.
# What it tests:
#   - A nonexistent path and an empty payload path are allowed.
test_allows_missing_path() {
  assert_eq 0 "$(guard_status "$T/new.md")" "exit for a new file"
  assert_eq 0 "$(guard_status "")" "exit for no path"
}

# Why this test is important:
#   - A guard that allows what it cannot read fails open.
# What it tests:
#   - Malformed JSON exits 2.
test_blocks_bad_json() {
  printf 'not json' | bash "$GUARD" >/dev/null 2>&1
  assert_eq 2 "$?" "exit for malformed payload"
}

# Why this test is important:
#   - Without jq the hook cannot read the payload; it must fail closed.
# What it tests:
#   - With no jq on PATH the guard exits 2.
test_blocks_without_jq() {
  printf '{"tool_input":{"file_path":"/x"}}' | env PATH="$T/empty" /bin/bash "$GUARD" >/dev/null 2>&1
  assert_eq 2 "$?" "exit without jq"
}

run_test test_blocks_go_generated
run_test test_blocks_marker_in_frontmatter
run_test test_blocks_marker_without_trailing_newline
run_test test_allows_plain_file
run_test test_allows_late_mention
run_test test_allows_missing_path
run_test test_blocks_bad_json
run_test test_blocks_without_jq
finish
